  kvgWechsel: {
    quelle: 'Sources: [[KVG Art. 7|https://www.fedlex.admin.ch/eli/cc/1995/1328_1328_1328/de#art_7]] (German text where no English exists, checked September 2026).',
    checkIntro: "A lower premium alone isn't a reason to switch. Pause for a moment — does the switch really fit?",
    checkPoint1: "Basic insurance covers the same legally defined benefits at every insurer. Switching doesn't change your coverage and doesn't interrupt ongoing treatment.",
    checkPoint2: 'A lower premium often comes with a savings model (family doctor, telemedicine, HMO) or a higher deductible. Does that fit your everyday needs?',
    checkPoint3: 'Supplementary insurance is separate and not guaranteed. Never cancel it prematurely — check it first.',
    checkZusatzLink: 'Check supplementary insurance first',
    title: 'Switch health insurer',
    intro: 'A calm path in four steps — compare, choose a new insurer, cancel, secure the deadline. You don\'t have to decide everything at once.',
    step1Title: '1 · Is switching worth it?',
    step1Text: 'Compare your premium with the alternatives in your canton.',
    step1TextKnown: 'Your current insurer: {insurer}. Compare the premium with the alternatives in your canton.',
    step1Link: 'Compare premiums',
    step2Title: '2 · New insurer — two ways',
    step2Intro: 'You can switch to the new insurer yourself, or let the new insurer handle the switch. Neither is «more correct».',
    path3aTitle: 'I sign up myself',
    path3aText: 'Apply to the new insurer (basic insurance).',
    path3aWarn: 'Only cancel once the new insurer has confirmed acceptance.',
    path3bTitle: 'The new insurer takes over',
    path3bText: 'Many insurers cancel the old one for you — with a power of attorney / switching service.',
    path3bReassure: 'Then the order is automatically safe.',
    uptakeReassure: 'Basic insurance has a duty to accept — no insurer may reject you.',
    step3Title: '3 · Write the cancellation',
    step3Text: 'Create the cancellation letter from the ready template — your insurer and policy number are already filled in.',
    step3Link: 'Create cancellation letter',
    step4Title: '4 · Secure the deadline',
    step4Text: 'The ordinary cancellation must reach the old insurer by 30 November {year}; if that day falls on a Saturday, Sunday or public holiday, by the last working day before (FOPH). Put the deadline in your calendar.',
    step4Button: 'Deadline {date} to calendar',
    step4Done: 'Noted in the calendar.',
    step4CalendarLink: 'To the calendar',
    policeLink: 'File the policy',
    reminderTitle: 'Cancel health insurer — deadline',
    reminderNotes: 'Ordinary cancellation of basic insurance by 30 Nov. Only cancel once the new insurer confirms acceptance (unless the new insurer handles the switch).',
    specialRight: 'Special right of cancellation: once the new premium is announced, you can switch with one month’s notice to the end of the month before the new premium applies (KVG Art. 7 para. 2) — even with savings models or a higher deductible.',
    chosen: 'Selected',
    step3Note3b: 'If the new insurer handles the switch, it takes care of the cancellation — you don\'t need to write a letter yourself.',
    wunschKasseLabel: 'Preferred insurer (optional)',
    wunschKassePlaceholder: 'Name of the insurer',
    reminderTitleTo: 'Switch to {insurer} — deadline',
    todoText: 'Switch health insurer: compare premiums',
    path3bCaveat: 'Not every insurer reliably does this — get written confirmation that the old policy was cancelled. Cancelling yourself is always the safe way.',
    debtNote: 'You can only switch if you have no outstanding premiums or arrears with your current insurer — otherwise it can block the switch. Settle any open amounts first.',
  },
