    modelFlat: 'flat-rate',
    noteApplySva: 'Apply at SVA {canton}',
    noteApplyAhvBranch: 'Apply at AHV branch office of your municipality',
    noteApplyAhvBranchShort: 'Apply at AHV branch office',
